from pathlib import Path
import numpy as np
import pandas as pd

CAPITAL = 20_000.0
SIZES = [10, 15, 20, 25, 50]

# Reads either plan2_monthly_selections.csv or id_strategy_selections.csv (generated by backtest_id.py)
CANDIDATE_FILES = [
    Path("plan2_monthly_selections.csv"),
    Path("id_strategy_selections.csv"),
]

selection_file = next((p for p in CANDIDATE_FILES if p.exists()), None)
if selection_file is None:
    raise SystemExit(
        "Neither plan2_monthly_selections.csv nor id_strategy_selections.csv was found. "
        "Run backtest_id.py first to generate historical monthly Plan 2 selections."
    )

df = pd.read_csv(selection_file)

# Normalize column aliases
rename_map = {}
if "rebalance_date" in df.columns and "Date" not in df.columns:
    rename_map["rebalance_date"] = "Date"
if "symbol" in df.columns and "Stock" not in df.columns:
    rename_map["symbol"] = "Stock"
if rename_map:
    df = df.rename(columns=rename_map)

required = {"Date", "Stock", "Price", "Next Month Return"}
missing = required - set(df.columns)
if missing:
    raise SystemExit(
        f"Missing columns in {selection_file}: {sorted(missing)}. "
        f"Found: {list(df.columns)}. Re-run backtest_id.py to populate Price and Next Month Return."
    )

df["Date"] = pd.to_datetime(df["Date"], errors="coerce")
df["Price"] = pd.to_numeric(df["Price"], errors="coerce")
df["Next Month Return"] = pd.to_numeric(df["Next Month Return"], errors="coerce")
df = df.dropna(subset=["Date", "Price", "Next Month Return"])
df = df[df["Price"] > 0].copy()

# CRITICAL: preserve Plan 2 ranking order (ID Rank / Rank / lowest ID), NEVER alphabetical by Stock
if "ID Rank" in df.columns:
    df["ID Rank"] = pd.to_numeric(df["ID Rank"], errors="coerce")
    df = df.sort_values(["Date", "ID Rank", "Stock"], ascending=[True, True, True])
elif "Rank" in df.columns:
    df["Rank"] = pd.to_numeric(df["Rank"], errors="coerce")
    df = df.sort_values(["Date", "Rank", "Stock"], ascending=[True, True, True])
elif "ID" in df.columns:
    df["ID"] = pd.to_numeric(df["ID"], errors="coerce")
    df = df.sort_values(["Date", "ID", "Stock"], ascending=[True, True, True])
else:
    # Preserve file order within each Date if no explicit rank column exists
    df["_row_order"] = np.arange(len(df))
    df = df.sort_values(["Date", "_row_order"], ascending=[True, True])

results = []

for n in SIZES:
    monthly = []

    for date, g in df.groupby("Date", sort=True):
        selected = g.head(n).copy()
        if selected.empty:
            continue

        # Equal target capital per selected stock, whole shares only.
        target = CAPITAL / n
        selected["Shares"] = np.floor(target / selected["Price"])
        selected["Invested"] = selected["Shares"] * selected["Price"]

        invested = float(selected["Invested"].sum())
        cash = CAPITAL - invested

        pnl = float((selected["Invested"] * selected["Next Month Return"]).sum())
        portfolio_return = pnl / CAPITAL

        monthly.append({
            "Date": date,
            "Return": portfolio_return,
            "Invested": invested,
            "Cash": cash,
            "Executable": int((selected["Shares"] >= 1).sum()),
        })

    if not monthly:
        continue

    m = pd.DataFrame(monthly).sort_values("Date")
    wealth = (1 + m["Return"]).cumprod()
    total = float(wealth.iloc[-1] - 1)
    years = len(m) / 12
    cagr = (1 + total) ** (1 / years) - 1 if years > 0 else np.nan
    vol = m["Return"].std(ddof=1) * np.sqrt(12)
    sharpe = (
        m["Return"].mean() / m["Return"].std(ddof=1) * np.sqrt(12)
        if m["Return"].std(ddof=1) > 0 else np.nan
    )
    dd = wealth / wealth.cummax() - 1

    results.append({
        "Stocks": n,
        "Months": len(m),
        "Total Return %": round(total * 100, 2),
        "CAGR %": round(cagr * 100, 2),
        "Volatility %": round(vol * 100, 2),
        "Sharpe": round(sharpe, 2) if pd.notna(sharpe) else np.nan,
        "Max Drawdown %": round(dd.min() * 100, 2),
        "Win Rate %": round((m["Return"] > 0).mean() * 100, 2),
        "Avg Invested ₹": round(m["Invested"].mean(), 2),
        "Avg Cash ₹": round(m["Cash"].mean(), 2),
        "Avg Executable Stocks": round(m["Executable"].mean(), 2),
    })

out = pd.DataFrame(results)
out.to_csv("capital_sizing_backtest.csv", index=False)

print(f"\n₹{CAPITAL:,.0f} CAPITAL SIZING BACKTEST (Source: {selection_file})")
print("=" * 110)
print(out.to_string(index=False))
print("=" * 110)
print("Created: capital_sizing_backtest.csv")
